import math

class SignInSystem:
    def __init__(self):
        self._users = {}

    @property
    def users(self):
        return self._users

    def add_user(self, username):
        if self._is_existing_user(username):
            return False
        self._register_user(username)
        return True

    def sign_in(self, username):
        if self._is_existing_user(username):
            self._mark_as_signed_in(username)
            return True
        return False

    def check_sign_in(self, username):
        return self._is_signed_in(username)

    def all_signed_in(self):
        return self._are_all_signed_in()

    def all_not_signed_in(self):
        return self._get_not_signed_in_users()

    def _is_existing_user(self, username):
        return username in self._users

    def _register_user(self, username):
        self._users[username] = False

    def _mark_as_signed_in(self, username):
        self._users[username] = True

    def _is_signed_in(self, username):
        return username in self._users and self._users[username]

    def _are_all_signed_in(self):
        return all(self._users.values()) if self._users else True

    def _get_not_signed_in_users(self):
        return [username for username, signed_in in self._users.items() if not signed_in]
